import { useContext } from "react";
import { LockContext } from "@/hooks/LockContext";
import { useFieldContext } from "@/hooks/formContext";
import "../text.css";
import "../label.css";
import LabelField from "./LabelField";

interface CheckboxFieldProps {
  label: string;
}

function CheckboxField({ label }: CheckboxFieldProps) {
  const field = useFieldContext<boolean>();
  const lockContext = useContext(LockContext);
  const isDisabled = !!lockContext?.lockAll;

  return (
    <div className="text-input">
      <LabelField label={label} htmlFor={label} />

      <div className="text-input__field-wrapper">
        <input
          type="checkbox"
          className={"text-input__input"}
          name={label}
          checked={field.state.value}
          disabled={isDisabled}
          onChange={(e) => field.handleChange(e.target.checked)}
        />
      </div>
    </div>
  );
}

export default CheckboxField;
