import { LockContext } from "@/hooks/LockContext";
import { useFieldContext } from "@/hooks/formContext";
import { useContext } from "react";
import "../text.css";
import "../label.css";

interface TextAreaProps {
  label: string;
  required?: boolean;
  enabled?: boolean;
  placeholder?: string;
  secret?: boolean;
  copy?: boolean;
  warning?: string;
  disabled?: boolean;
  hasCheckbox?: boolean;
  onCheckboxChange?: (checked: boolean) => void;
}

function TextArea({
  label,
  required = false,
  enabled,
  placeholder,
  warning,
  disabled = false,
  hasCheckbox,
  onCheckboxChange,
}: TextAreaProps) {
  const field = useFieldContext<string>();
  const lockContext = useContext(LockContext);
  const isDisabled = disabled || enabled === false || lockContext?.lockAll;

  return (
    <div className="text-input__field-wrapper">
      <textarea
        className={"text-input__input"}
        name={label}
        value={field.state.value}
        placeholder={placeholder ?? ""}
        required={required}
        disabled={isDisabled}
        onChange={(e) => field.handleChange(e.target.value)}
      />
      {warning && <div className="text-input__validation">{warning}</div>}
    </div>
  );
}

export default TextArea;
