import { LockContext } from "@/hooks/LockContext";
import { useFieldContext } from "@/hooks/formContext";
import { useContext, useState } from "react";
import { ToggleGroup, ScrollArea } from "radix-ui";
import "./togglegroup.css";
import LabelField from "./LabelField";

interface ToggleGroupFieldProps {
  label: string;
  options: Record<string, string> | string[];
  hasCheckbox?: boolean;
  onCheckboxChange?: (checked: boolean) => void;
}

function ToggleGroupField({
  label,
  options,
  hasCheckbox,
  onCheckboxChange,
}: ToggleGroupFieldProps) {
  const field = useFieldContext<string[]>();
  const [checked, setChecked] = useState<boolean>(
    field.state.value?.length > 0,
  );
  const Options = Array.isArray(options)
    ? options.reduce(
        (acc, curr) => {
          acc[curr] = curr;
          return acc;
        },
        {} as Record<string, string>,
      )
    : options;
  const lockContext = useContext(LockContext);
  const isDisabled = !checked || lockContext?.lockAll;
  const handleCheckboxChange = (value: boolean) => {
    setChecked(value);
    onCheckboxChange?.(value);
  };

  return (
    <div className="toggleGroupField">
      <LabelField
        label={label}
        htmlFor={label}
        hasCheckbox={hasCheckbox}
        checked={checked}
        onCheckboxChange={handleCheckboxChange}
      />

      <ScrollArea.Root className="ScrollAreaRoot">
        <ScrollArea.Viewport className="ScrollAreaViewport">
          <ToggleGroup.Root
            className="toggleGroupField__options"
            type="multiple"
            disabled={isDisabled}
            value={field.state.value || []}
            onValueChange={field.handleChange}
          >
            {Object.entries(Options).map(([key, value]) => (
              <ToggleGroup.Item
                className="toggleGroupField__option"
                key={key}
                value={key}
              >
                {value}
              </ToggleGroup.Item>
            ))}
          </ToggleGroup.Root>
        </ScrollArea.Viewport>

        <ScrollArea.Scrollbar
          className="ScrollAreaScrollbar"
          orientation="vertical"
        >
          <ScrollArea.Thumb className="ScrollAreaThumb" />
        </ScrollArea.Scrollbar>
      </ScrollArea.Root>
    </div>
  );
}

export default ToggleGroupField;
