import type { ReactNode } from "react";
import type { LabelOptions } from "../../types";
import LabelField from "./LabelField";
import "../text.css";

interface FieldCheckbox {
  checked: boolean;
  onChange: (checked: boolean) => void;
  id?: string;
  name?: string;
  disabled?: boolean;
  ariaLabel?: string;
}

interface FieldProps {
  label: string;
  htmlFor: string;
  children: ReactNode;
  checkbox?: FieldCheckbox;
  labelOptions?: LabelOptions;
  className?: string;
}

function InputField({
  label,
  htmlFor,
  children,
  checkbox,
  labelOptions,
  className = "text-input",
}: FieldProps) {
  return (
    <div className={className}>
      <LabelField
        label={label}
        htmlFor={htmlFor}
        labelOptions={labelOptions}
        hasCheckbox={checkbox !== undefined}
        checked={checkbox?.checked}
        onCheckboxChange={checkbox?.onChange}
        checkboxId={checkbox?.id}
        checkboxName={checkbox?.name}
        checkboxDisabled={checkbox?.disabled}
        checkboxAriaLabel={checkbox?.ariaLabel ?? `${label} enabled`}
      />
      {children}
    </div>
  );
}

export default InputField;
