const StorageBaseSchema = z.object({
  relativemountpath: z.string().trim(),
  readonly: z.boolean().default(false),
});

const B2DropSchema = StorageBaseSchema.extend({
  template: z.literal("b2drop"),
  user: z.optional(z.string().trim()),
  obscure_pass: z.optional(z.string().trim()),
  path: z.optional(z.string().trim()),
});

const AWSSchema = StorageBaseSchema.extend({
  template: z.literal("aws"),
  access_key_id: z.optional(z.string().trim()),
  secret_access_key: z.optional(z.string().trim()),
  remotepath: z.optional(z.string().trim()),
  region: z.string().trim().default(REGION[0].value),
});

const S3CompatibleProviderSchema = StorageBaseSchema.extend({
  template: z.literal("s3"),
  access_key_id: z.optional(z.string().trim()),
  secret_access_key: z.optional(z.string().trim()),
  provider: z.string().trim().default(PROVIDER[0].value),
  remotepath: z.string().trim().default("bucketname"),
  endpoint: z.optional(z.string().trim()),
  region: z.optional(z.string().trim()),
});

const WebdavSchema = StorageBaseSchema.extend({
  template: z.literal("webdav"),
  user: z.optional(z.string().trim()),
  obscure_pass: z.optional(z.string().trim()),
  path: z.string().trim().default("/"),
  url: z.string().trim().default("https://b2drop.eudat.eu/remote.php/webdav/"),
  vendor: z.string().trim().default(VendorOptions[0].value),
  bearer_token: z.optional(z.string().trim()),
});

export const StorageSchema = z.discriminatedUnion("template", [
  B2DropSchema,
  AWSSchema,
  S3CompatibleProviderSchema,
  WebdavSchema,
]);

export type storageType = z.infer<typeof StorageSchema>;

const customSchema = z.optional(
  z.object({
    privaterepopassword: z.optional(z.string().trim()),
    ...baseCustomSchema.shape,
  }),
);

const hpcSchema = z.optional(
  z.object({
    ...baseHpcSchema.shape,
    account: z.optional(z.string().trim()),
  }),
);

export const formSchema = z.object({
  name: z.string().trim().min(1, "Name is required"),
  service: z.optional(z.string().trim()),
  option: z.string().trim(),
  profile: z.string().trim(),
  system: z.string().trim(),
  flavor: z.optional(z.string().trim()),
  modules: modulesSchema,
  modules_versions: modulesVersionsSchema,
  envvariables: z.optional(z.array(envVariableSchema)),
  workshop_id: z.optional(z.boolean()), // Remove optional after testing
  secret_keys: z.array(z.string().trim()).default([]),
  share_id: z.optional(z.string().trim()),
  resources: resourcesSchema,
  storage: z.object({
    mounts: z.array(StorageSchema),
    localstoragepath: z
      .optional(z.string().trim())
      .prefault("/home/jovyan/work"),
  }),

  repo2dockerdirectlink: z.optional(z.string().trim()),
  repo2docker: repo2dockerSchema,
  custom: customSchema,
  hpc: hpcSchema,
});

export type FormType = z.infer<typeof formSchema>;

