import * as z from "zod";

// Shared
export const REPOTYPE = [
  { value: "gh", label: "GitHub" },
  { value: "git", label: "Git repository" },
  { value: "gl", label: "GitLab" },
  { value: "gist", label: "GitHub Gist" },
  { value: "zenodo", label: "Zenodo DOI" },
  { value: "figshare", label: "FigShare DOI" },
  { value: "hydroshare", label: "Hydroshare resource" },
  { value: "dataverse", label: "Dataverse DOI" },
  { value: "ckan", label: "CKAN dataset" },
] as const;

export const REPOPATHTYPE = [
  { value: "file", label: "File" },
  { value: "url", label: "URL" },
] as const;

export const repo2dockerSchema = z.optional(
  z.object({
    repotype: z.enum(REPOTYPE.map((r) => r.value)).default(REPOTYPE[0].value),
    repourl: z.string().trim().default(""),
    reporef: z.optional(z.string().trim()),
    repopath: z.optional(z.string().trim()),
    repopathtype: z
      .enum(REPOPATHTYPE.map((r) => r.value))
      .default(REPOPATHTYPE[0].value),
    image: z.optional(z.string().trim()),
  }),
);

export const baseCustomSchema = z.object({
  customimage: z.string().trim().default("jupyter/datascience-notebook"),
  privaterepo: z.optional(z.string().trim()),
  privaterepousername: z.optional(z.string().trim()),
});

export const baseHpcSchema = z.object({
  partition: z.optional(z.string().trim()),
  project: z.optional(z.string().trim()),
  reservation: z.optional(z.string().trim()),
});

export const resourcesSchema = z.optional(
  z.object({
    nodes: z.optional(z.string().trim()),
    runtime: z.optional(z.string().trim()),
    gpus: z.optional(z.string().trim()),
    xserver: z.optional(z.string().trim()),
  }),
);

export const envVariableSchema = z.record(
  z.string(),

  z.string().trim(),
);

export const modulesSchema = z.optional(
  z.record(z.string(), z.array(z.string().trim())),
);

export const modulesVersionsSchema = z.optional(
  z.record(z.string(), z.array(z.string().trim())),
);
