import * as z from "zod";

import { repo2dockerSchema } from "@/components/form/config/schema";

export type Repo2DockerConfig = NonNullable<z.infer<typeof repo2dockerSchema>>;

export type Repo2DockerBuildPhase =
  | "waiting"
  | "fetching"
  | "building"
  | "pushing"
  | "ready"
  | "built"
  | "launching"
  | "failed"
  | (string & {});

export type Repo2DockerBuildStatus =
  "idle" | "waiting" | "fetching" | "building" | "pushing" | "ready" | "failed";

export interface Repo2DockerBuildMessage {
  phase: Repo2DockerBuildPhase;
  message?: string;
  imageName?: string;
  raw: unknown;
}

export interface Repo2DockerBuildProgress extends Repo2DockerBuildMessage {
  status: Repo2DockerBuildStatus;
  progress: number;
}

export interface Repo2DockerBuildCallbacks {
  onProgress?: (event: Repo2DockerBuildProgress) => void;
  onReady?: (event: Repo2DockerBuildProgress & { imageName?: string }) => void;
  onFailed?: (event: Repo2DockerBuildProgress) => void;
  onMessage?: (message: string, event: Repo2DockerBuildMessage) => void;
  onTimeout?: () => void;
  onError?: (error: unknown) => void;
  onClose?: () => void;
}

export interface Repo2DockerBuildSession {
  readonly url: string;
  close(): void;
}

export interface Repo2DockerService {
  repo2DockerSSE(
    repo2DockerConfig: Repo2DockerConfig,
    callbacks?: Repo2DockerBuildCallbacks,
    timeoutMs?: number,
  ): Repo2DockerBuildSession;
}

const BUILD_ONLY_PHASES = new Set(["ready", "built", "launching"]);
const ENCODE_REPO_URL_PHASES = new Set(["git", "gl", "hydroshare", "ckan"]);

const PROGRESS_BY_PHASE: Partial<Record<Repo2DockerBuildPhase, number>> = {
  waiting: 2,
  fetching: 3,
  building: 5,
  pushing: 8,
};

function normalizeRepoRef(repoRef: string | undefined) {
  return repoRef && repoRef.trim() !== "" ? repoRef : "HEAD";
}

function buildRepo2DockerUrl(repo2DockerConfig: Repo2DockerConfig): URL {
  const type = repo2DockerConfig.repotype;
  const repourl = ENCODE_REPO_URL_PHASES.has(type)
    ? encodeURIComponent(repo2DockerConfig.repourl)
    : repo2DockerConfig.repourl;
  const reporef = normalizeRepoRef(repo2DockerConfig.reporef);
  const url = new URL(
    `/services/binder/build/${type}/${repourl}/${reporef}`,
    window.location.origin,
  );
  url.searchParams.set("build_only", "true");
  return url;
}

function toBuildStatus(phase: Repo2DockerBuildPhase): Repo2DockerBuildStatus {
  if (phase === "waiting") return "waiting";
  if (phase === "fetching") return "fetching";
  if (phase === "building") return "building";
  if (phase === "pushing") return "pushing";
  if (BUILD_ONLY_PHASES.has(phase)) return "ready";
  if (phase === "failed") return "failed";
  return "idle";
}

function buildProgressForPhase(phase: Repo2DockerBuildPhase): number {
  return PROGRESS_BY_PHASE[phase] ?? 100;
}

function parseBuildMessage(raw: string): Repo2DockerBuildMessage {
  const parsed = JSON.parse(raw) as Partial<Repo2DockerBuildMessage> & {
    phase?: string;
  };

  return {
    phase: (parsed.phase ?? "") as Repo2DockerBuildPhase,
    message: parsed.message,
    imageName: parsed.imageName,
    raw: parsed,
  };
}

function createRepo2DockerBuildProgress(
  message: Repo2DockerBuildMessage,
): Repo2DockerBuildProgress {
  const status = toBuildStatus(message.phase);
  return {
    ...message,
    status,
    progress: buildProgressForPhase(message.phase),
  };
}

function createRepo2DockerService(): Repo2DockerService {
  return {
    repo2DockerSSE(repo2DockerConfig, callbacks = {}, timeoutMs = 30_000) {
      const url = buildRepo2DockerUrl(repo2DockerConfig);
      const eventSource = new EventSource(url);
      let closed = false;
      let completed = false;

      const close = () => {
        if (closed) return;
        closed = true;
        eventSource.close();
        callbacks.onClose?.();
      };

      const timeout = setTimeout(() => {
        if (!completed) {
          callbacks.onTimeout?.();
          close();
        }
      }, timeoutMs);

      const clearTimeoutIfNeeded = () => {
        clearTimeout(timeout);
      };

      eventSource.onmessage = (event) => {
        if (closed) {
          return;
        }

        try {
          const message = parseBuildMessage(event.data);
          const progress = createRepo2DockerBuildProgress(message);

          callbacks.onProgress?.(progress);

          if (message.message) {
            callbacks.onMessage?.(message.message, message);
          }

          if (BUILD_ONLY_PHASES.has(message.phase)) {
            completed = true;
            callbacks.onReady?.(progress);
            clearTimeoutIfNeeded();
            close();
            return;
          }

          if (message.phase === "failed") {
            completed = true;
            callbacks.onFailed?.(progress);
            clearTimeoutIfNeeded();
            close();
          }
        } catch (error) {
          clearTimeoutIfNeeded();
          callbacks.onError?.(error);
          close();
        }
      };

      eventSource.onerror = (error) => {
        clearTimeoutIfNeeded();
        if (!closed) {
          callbacks.onError?.(error);
        }
        close();
      };

      return {
        url: url.toString(),
        close: () => {
          clearTimeoutIfNeeded();
          close();
        },
      };
    },
  };
}

export const repo2DockerService = createRepo2DockerService();

export function useRepo2DockerService(): Repo2DockerService {
  return repo2DockerService;
}
