import { useContext, useState } from "react";
import LabelField from "./LabelField";
import TextArea from "./TextArea";
import TextInput from "./TextInput";
import { LockContext } from "@/hooks/LockContext";
import { useFieldContext } from "@/hooks/formContext";

interface TextFieldProps {
  type?: "input" | "textarea";
  label: string;
  required?: boolean;
  enabled?: boolean;
  placeholder?: string;
  secret?: boolean;
  copy?: boolean;
  pattern?: string;
  warning?: string;
  disabled?: boolean;
  hasCheckbox?: boolean;
  onCheckboxChange?: (checked: boolean) => void;
}

function TextField({
  type = "input",
  label,
  required = false,
  enabled,
  placeholder,
  secret = false,
  copy = false,
  pattern,
  warning,
  disabled = false,
  hasCheckbox,
  onCheckboxChange,
}: TextFieldProps) {
  const field = useFieldContext<string>();
  const lockContext = useContext(LockContext);
  const [checked, setChecked] = useState<boolean>(!!field.state.value);
  const isDisabled =
    disabled ||
    enabled === false ||
    (hasCheckbox && !checked) ||
    lockContext?.lockAll;

  const handleCheckboxChange = (value: boolean) => {
    setChecked(value);
    onCheckboxChange?.(value);
  };
  return (
    <div className="text-input">
      <LabelField
        label={label}
        htmlFor={label}
        hasCheckbox={hasCheckbox}
        checked={checked}
        onCheckboxChange={handleCheckboxChange}
      />
      {type === "input" ? (
        <TextInput
          label={label}
          required={required}
          enabled={enabled}
          placeholder={placeholder}
          secret={secret}
          copy={copy}
          pattern={pattern}
          disabled={isDisabled}
          warning={warning}
        />
      ) : (
        <TextArea
          label={label}
          required={required}
          enabled={enabled}
          placeholder={placeholder}
          copy={copy}
          disabled={isDisabled}
          warning={warning}
        />
      )}
    </div>
  );
}
export default TextField;
