import { LockContext } from "@/hooks/LockContext";
import { useFieldContext } from "@/hooks/formContext";
import { PlusIcon, TrashIcon } from "@radix-ui/react-icons";
import { useContext, useState } from "react";
import LabelField from "./LabelField";
import "../envForm.css";

interface EnvAdderFieldProps {
  label: string;
  hasCheckbox?: boolean;
  onCheckboxChange?: (checked: boolean) => void;
}

function EnvAdder({
  label,
  hasCheckbox,
  onCheckboxChange,
}: EnvAdderFieldProps) {
  const field = useFieldContext<Record<string, string>>();
  const envVariables = field.state.value ?? {};
  const [checked, setChecked] = useState<boolean>(
    Object.keys(envVariables).length > 0,
  );
  const [newEnv, setNewEnv] = useState("");
  const lockContext = useContext(LockContext);
  const isDisabled = Boolean(lockContext?.lockAll || (hasCheckbox && !checked));
  const handleCheckboxChange = (value: boolean) => {
    setChecked(value);
    onCheckboxChange?.(value);
  };

  const handleAddEnv = () => {
    const separatorIndex = newEnv.indexOf("=");
    if (separatorIndex <= 0) {
      return;
    }

    const name = newEnv.slice(0, separatorIndex).trim();
    const value = newEnv.slice(separatorIndex + 1);
    if (!name) {
      return;
    }

    field.handleChange({ ...envVariables, [name]: value });
    setNewEnv("");
  };

  const handleRemoveEnv = (env: string) => {
    const updatedEnvs = { ...envVariables };
    delete updatedEnvs[env];
    field.handleChange(updatedEnvs);
  };

  const handleUpdateEnv = (previousName: string, rawEnv: string) => {
    const separatorIndex = rawEnv.indexOf("=");
    if (separatorIndex <= 0) {
      return;
    }

    const name = rawEnv.slice(0, separatorIndex).trim();
    if (!name) {
      return;
    }

    const updatedEnvs = { ...envVariables };
    delete updatedEnvs[previousName];
    updatedEnvs[name] = rawEnv.slice(separatorIndex + 1);
    field.handleChange(updatedEnvs);
  };

  return (
    <div style={{ display: "flex", alignItems: "flex-start", width: "100%" }}>
      <LabelField
        label={label}
        htmlFor={label}
        hasCheckbox={hasCheckbox}
        checked={checked}
        onCheckboxChange={handleCheckboxChange}
      />

      <div className="env-variables-entry" style={{ flex: 1 }}>
        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
          <input
            type="text"
            className="env-variables-entry__input"
            value={newEnv}
            onChange={(event) => setNewEnv(event.target.value)}
            placeholder="EnvName=EnvValue"
            disabled={isDisabled}
            aria-label="New environment variable"
          />
          <button
            type="button"
            className="env-variables-entry__add-btn"
            style={{ backgroundColor: "#0d6efd", height: "2rem", margin: 0 }}
            onClick={handleAddEnv}
            disabled={isDisabled || !newEnv.includes("=")}
            aria-label="Add environment variable"
          >
            <PlusIcon />
          </button>
        </div>
        {Object.entries(envVariables).map(([key, value], index) => (
          <div
            key={index}
            style={{
              display: "flex",
              alignItems: "center",
              gap: "0.5rem",
              marginTop: "0.5rem",
            }}
          >
            <input
              type="text"
              className="env-variables-entry__input"
              value={`${key}=${value}`}
              onChange={(event) => handleUpdateEnv(key, event.target.value)}
              disabled={isDisabled}
              aria-label={`Environment variable ${key}`}
            />
            <button
              type="button"
              className="env-variables-entry__remove-btn"
              style={{ height: "2rem", flexShrink: 0 }}
              onClick={() => handleRemoveEnv(key)}
              disabled={isDisabled}
              aria-label={`Remove environment variable ${key}`}
            >
              <TrashIcon />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default EnvAdder;
