import { useFormContext } from "@/hooks/formContext";
import { formSchema, type FormType } from "../config/schema";
import { getAuthState } from "@/utils/authStateHelper";
import {
  collect,
  resolveCollectionTypeFromForm,
  type Repo2DockerPayload,
} from "@/api/CollectStrategy";
import { useServerService } from "@/api/ServerService";
import { useRepo2DockerService } from "@/api/R2DService";
import { TriangleRightIcon } from "@radix-ui/react-icons";
import Button from "@/components/Button/Button";
import { useTabContext } from "@/hooks/TabContext";
import { useRowContext } from "@/hooks/RowContext";
import { useR2DStore } from "@/stores/R2DStore";
import { useConfigContext } from "@/hooks/ConfigContext";

export function StartButton() {
  const configID = useConfigContext().configID;
  const rowContext = useRowContext();
  const tabContext = useTabContext();
  const form = useFormContext();
  const serverService = useServerService();
  const repo2DockerService = useRepo2DockerService();
  const clearR2DLogs = useR2DStore((state) => state.clearLogs);
  const appendR2DLog = useR2DStore((state) => state.appendLog);
  const authState = getAuthState();

  function openStartPage() {
    const startUrl = new URL(
      `/start/${authState.name}/${configID}`,
      window.origin,
    );
    window.open(startUrl, "_blank");
  }

  async function startServerWithPayload(user: string, payload: unknown) {
    try {
      const response = await serverService.startNamedServer(
        user,
        configID,
        payload,
      );

      if (!response) {
        console.error("Server start request failed");
      }
    } catch (error) {
      console.error("Server start request failed:", error);
    }
  }

  async function handleStartServer() {
    const values = form.state.values as unknown as FormType;
    const validation = formSchema.safeParse(values);

    if (!validation.success) {
      console.error("Form validation errors:", validation.error.flatten());
      return;
    }

    const collectionType = resolveCollectionTypeFromForm(
      values.option,
      values.system,
    );

    if (!collectionType) {
      console.warn(
        `Skipping collection strategy for unsupported option "${values.option}".`,
      );
      console.log("Current form values:", values);
      return;
    }

    const user = getAuthState().name;

    try {
      openStartPage();
      if (!rowContext.isRowOpen) {
        rowContext.openRow();
      }
      tabContext.setActiveTab("logs");

      if (collectionType === "repo2docker") {
        const payload = collect("repo2docker", values);
        clearR2DLogs(configID);
        appendR2DLog(configID, "Starting Repo2Docker build...");
        repo2DockerService.repo2DockerSSE(payload.repo2docker, {
          onProgress: ({ phase, progress, message }) => {
            appendR2DLog(configID, `Phase: ${phase} (${progress}%)`);
            if (message) {
              appendR2DLog(configID, message);
            }
          },
          onMessage: (message) => {
            appendR2DLog(configID, message);
          },
          onReady: ({ imageName }) => {
            appendR2DLog(
              configID,
              `Repo2Docker build complete${imageName ? `: ${imageName}` : ""}`,
            );

            const repo2DockerPayload: Repo2DockerPayload = {
              ...payload,
              repo2docker: {
                ...payload.repo2docker,
                image: imageName ?? payload.repo2docker.image,
              },
            };

            void startServerWithPayload(user, repo2DockerPayload);
          },
          onFailed: () => {
            console.error("Repo2Docker build failed");
            appendR2DLog(configID, "Repo2Docker build failed");
          },
          onTimeout: () => {
            console.error("Repo2Docker build timed out");
            appendR2DLog(configID, "Repo2Docker build timed out");
          },
          onError: (error) => {
            console.error("Repo2Docker build error:", error);
            appendR2DLog(configID, `Repo2Docker build error: ${String(error)}`);
          },
        });
        return;
      }

      const payload = collect(collectionType, values);
      console.log(
        `Starting server for user ${user} with service and config ${configID} and payload:`,
      );
      console.log("Collected payload:", payload);
      console.log("collected body", JSON.stringify(payload));
      await startServerWithPayload(user, payload);
    } catch (error) {
      console.error("Failed to collect server payload:", error);
    }
  }

  return (
    <form.Subscribe selector={(state) => state.isSubmitting}>
      {(isSubmitting) => (
        <Button
          type="submit"
          color="primary"
          disabled={isSubmitting}
          icon={<TriangleRightIcon />}
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            void handleStartServer();
          }}
        >
          start
        </Button>
      )}
    </form.Subscribe>
  );
}
