import { create } from "zustand";

const EMPTY_LOGS: string[] = [];

interface R2DStore {
  logsByConfigId: Record<string, string[]>;
  appendLog: (configId: string, line: string) => void;
  clearLogs: (configId: string) => void;
}

export const useR2DStore = create<R2DStore>((set) => ({
  logsByConfigId: {},
  appendLog: (configId, line) =>
    set((state) => ({
      logsByConfigId: {
        ...state.logsByConfigId,
        [configId]: [...(state.logsByConfigId[configId] ?? []), line],
      },
    })),
  clearLogs: (configId) =>
    set((state) => ({
      logsByConfigId: {
        ...state.logsByConfigId,
        [configId]: [],
      },
    })),
}));

export function useR2DLogs(configId: string) {
  return useR2DStore((state) => state.logsByConfigId[configId] ?? EMPTY_LOGS);
}
